                return -1;
        }
        tmp = init_env;
        for (env = environ; *env; env++) {
                *tmp = strdup(*env);
                if (*tmp == NULL) {
                        ha_alert("Cannot allocate memory to backup env variable '%s'.\n",
                                 *env);
                        return -1;
                }
                tmp++;
        }
        /* last entry */
        *tmp = NULL;

        return 0;
}

